#!/usr/bin/env node
// Generated by BootAgent. Do not edit: BootAgent rewrites this Skill when its
// model or Provider changes.
//
// Calls one multimodal model on the user's own Provider. Node 18 or later, no
// dependencies. The API key comes from the environment variable named in
// config.json, or from BootAgent's private fallback file; it is never printed.

import { existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { basename, dirname, extname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const EXIT = { ok: 0, internal: 1, usage: 2, setup: 3, refused: 4, key: 5, unavailable: 6 };
const MiB = 1024 * 1024;
const LIMITS = { image: 20 * MiB, audio: 25 * MiB, download: 50 * MiB, speech: 50 * MiB };

class Failure extends Error {
  constructor(code, message) {
    super(message);
    this.code = code;
  }
}

let secret = "";

// The key never reaches output, even when a provider echoes the request back.
function redact(text) {
  let value = String(text ?? "");
  if (secret) value = value.split(secret).join("[redacted]");
  return value.replace(/Bearer\s+[^\s"']+/g, "Bearer [redacted]");
}

function fail(code, message) {
  throw new Failure(code, message);
}

const here = dirname(fileURLToPath(import.meta.url));

function loadConfig() {
  const path = join(here, "..", "config.json");
  let config;
  try {
    config = JSON.parse(readFileSync(path, "utf8"));
  } catch {
    fail(EXIT.setup, "config.json next to this Skill is missing or invalid. Reinstall the Skill from BootAgent.");
  }
  for (const field of ["capability", "adapter", "model", "base_url", "key_env"]) {
    if (typeof config[field] !== "string" || !config[field]) fail(EXIT.setup, `config.json has no ${field}. Reinstall the Skill from BootAgent.`);
  }
  if (!/^https?:\/\//.test(config.base_url)) fail(EXIT.setup, "config.json has an invalid base_url. Reinstall the Skill from BootAgent.");
  return config;
}

function expandHome(path) {
  if (path === "~") return homedir();
  if (path.startsWith("~/") || path.startsWith("~\\")) return join(homedir(), path.slice(2));
  return path;
}

// Same quoting BootAgent writes: bare, or single-quoted with \' and \\.
function parseEnvFile(text, name) {
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) continue;
    const eq = line.indexOf("=");
    if (eq < 0 || line.slice(0, eq).trim() !== name) continue;
    let value = line.slice(eq + 1).trim();
    if (value.length >= 2 && value.startsWith("'") && value.endsWith("'")) {
      value = value.slice(1, -1).replace(/\\(['\\])/g, "$1");
    } else if (value.length >= 2 && value.startsWith('"') && value.endsWith('"')) {
      value = value.slice(1, -1).replace(/\\(["\\])/g, "$1");
    }
    return value;
  }
  return "";
}

function loadKey(config) {
  let key = process.env[config.key_env] ?? "";
  if (!key && typeof config.key_file === "string" && config.key_file) {
    const path = expandHome(config.key_file);
    if (existsSync(path)) {
      try {
        key = parseEnvFile(readFileSync(path, "utf8"), config.key_env);
      } catch {
        key = "";
      }
    }
  }
  key = key.trim();
  if (!key) {
    fail(EXIT.setup, `No API key found in ${config.key_env}. Restart the Agent so it picks up the variable BootAgent wrote, or reinstall the Skill from BootAgent.`);
  }
  secret = key;
  return key;
}

function parseArgs(argv) {
  const options = { _: [] };
  for (let index = 0; index < argv.length; index++) {
    const arg = argv[index];
    if (!arg.startsWith("--")) {
      options._.push(arg);
      continue;
    }
    const name = arg.slice(2);
    if (name === "help") {
      options.help = true;
      continue;
    }
    const value = argv[index + 1];
    if (value === undefined || value.startsWith("--")) fail(EXIT.usage, `--${name} needs a value.`);
    index++;
    if (name === "image") (options.image ??= []).push(value);
    else options[name] = value;
  }
  return options;
}

function positiveInt(value, name, fallback, max) {
  if (value === undefined) return fallback;
  const number = Number(value);
  if (!Number.isInteger(number) || number < 1 || number > max) fail(EXIT.usage, `--${name} must be a whole number from 1 to ${max}.`);
  return number;
}

function readInput(path, limit, kind) {
  const full = resolve(path);
  let info;
  try {
    info = statSync(full);
  } catch {
    fail(EXIT.usage, `${kind} file not found: ${path}`);
  }
  if (!info.isFile()) fail(EXIT.usage, `${kind} path is not a file: ${path}`);
  if (info.size > limit) fail(EXIT.usage, `${kind} file is larger than ${Math.round(limit / MiB)} MB: ${path}`);
  return readFileSync(full);
}

const IMAGE_TYPES = { ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".webp": "image/webp", ".gif": "image/gif" };

function stamp() {
  return new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
}

function freePath(path) {
  if (!existsSync(path)) return path;
  const extension = extname(path);
  const stem = path.slice(0, path.length - extension.length);
  for (let counter = 2; ; counter++) {
    const candidate = `${stem}-${counter}${extension}`;
    if (!existsSync(candidate)) return candidate;
  }
}

function writeOutput(path, data) {
  const target = freePath(resolve(path));
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, data);
  return target;
}

function detail(text) {
  let message = text;
  try {
    const parsed = JSON.parse(text);
    const error = parsed?.error;
    message = (typeof error === "string" && error) || error?.message || parsed?.message || parsed?.detail || text;
  } catch {
    // Not JSON; keep the text.
  }
  message = redact(String(message)).replace(/\s+/g, " ").trim();
  if (/^</.test(message)) return "";
  return message.length > 400 ? `${message.slice(0, 400)}…` : message;
}

async function call(config, key, path, init, timeoutMs) {
  const url = config.base_url.replace(/\/+$/, "") + path;
  let response;
  try {
    response = await fetch(url, {
      ...init,
      headers: { ...(init.headers ?? {}), Authorization: `Bearer ${key}` },
      signal: AbortSignal.timeout(timeoutMs),
    });
  } catch (error) {
    if (error?.name === "TimeoutError" || error?.name === "AbortError") fail(EXIT.unavailable, `The provider did not answer within ${Math.round(timeoutMs / 1000)} s.`);
    fail(EXIT.unavailable, `Cannot reach the provider: ${redact(error?.cause?.code ?? error?.message ?? error)}`);
  }
  if (response.ok) return response;
  const said = detail(await response.text().catch(() => ""));
  const suffix = said ? `: ${said}` : ".";
  if (response.status === 401 || response.status === 403) fail(EXIT.key, `The provider rejected the API key (HTTP ${response.status})${suffix}`);
  if (response.status === 408 || response.status === 429 || response.status >= 500) fail(EXIT.unavailable, `The provider is busy or failing (HTTP ${response.status})${suffix}`);
  fail(EXIT.refused, `The provider refused the request (HTTP ${response.status})${suffix}`);
}

async function json(response) {
  try {
    return await response.json();
  } catch {
    fail(EXIT.unavailable, "The provider returned a response that is not JSON.");
  }
}

// Result URLs are pre-signed and may be on another host, so the key is not
// sent with them.
async function download(url, timeoutMs) {
  let response;
  try {
    response = await fetch(url, { signal: AbortSignal.timeout(timeoutMs) });
  } catch {
    fail(EXIT.unavailable, "Cannot download the result from the provider.");
  }
  if (!response.ok) fail(EXIT.unavailable, `Cannot download the result (HTTP ${response.status}).`);
  const data = Buffer.from(await response.arrayBuffer());
  if (data.length > LIMITS.download) fail(EXIT.unavailable, "The result is larger than expected and was not saved.");
  return data;
}

function imageExtension(data) {
  if (data.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return ".png";
  if (data[0] === 0xff && data[1] === 0xd8) return ".jpg";
  if (data.subarray(0, 4).toString("latin1") === "RIFF" && data.subarray(8, 12).toString("latin1") === "WEBP") return ".webp";
  if (data.subarray(0, 3).toString("latin1") === "GIF") return ".gif";
  return ".png";
}

async function describe(config, key, options, timeoutMs) {
  const images = options.image ?? [];
  if (!images.length) fail(EXIT.usage, "Give at least one --image.");
  if (images.length > 8) fail(EXIT.usage, "Give at most 8 images.");
  const content = [{ type: "text", text: options.prompt || "Describe this image." }];
  for (const path of images) {
    const type = IMAGE_TYPES[extname(path).toLowerCase()];
    if (!type) fail(EXIT.usage, `Unsupported image type: ${path} (use PNG, JPEG, WebP or GIF).`);
    const data = readInput(path, LIMITS.image, "Image");
    content.push({ type: "image_url", image_url: { url: `data:${type};base64,${data.toString("base64")}` } });
  }
  const response = await call(config, key, "/chat/completions", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: config.model,
      messages: [{ role: "user", content }],
      max_tokens: positiveInt(options["max-tokens"], "max-tokens", 1024, 32768),
    }),
  }, timeoutMs);
  const body = await json(response);
  const text = body?.choices?.[0]?.message?.content;
  const answer = Array.isArray(text) ? text.map((part) => part?.text ?? "").join("") : text;
  if (typeof answer !== "string") fail(EXIT.unavailable, "The provider returned no text.");
  process.stdout.write(answer.trim() + "\n");
}

async function generate(config, key, options, timeoutMs) {
  if (!options.prompt) fail(EXIT.usage, "Give a --prompt.");
  const count = positiveInt(options.n, "n", 1, 4);
  const request = { model: config.model, prompt: options.prompt, n: count };
  if (options.size) request.size = options.size;
  const response = await call(config, key, "/images/generations", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(request),
  }, timeoutMs);
  const body = await json(response);
  const items = Array.isArray(body?.data) ? body.data : [];
  if (!items.length) fail(EXIT.unavailable, "The provider returned no image.");
  const directory = resolve(options.out || config.output_dir || "bootagent-output");
  const base = `image-${stamp()}`;
  const saved = [];
  for (const [index, item] of items.entries()) {
    let data;
    if (typeof item?.b64_json === "string") data = Buffer.from(item.b64_json, "base64");
    else if (typeof item?.url === "string") data = await download(item.url, timeoutMs);
    else continue;
    const name = items.length > 1 ? `${base}-${index + 1}` : base;
    saved.push(writeOutput(join(directory, name + imageExtension(data)), data));
  }
  if (!saved.length) fail(EXIT.unavailable, "The provider returned no image data.");
  process.stdout.write(saved.join("\n") + "\n");
}

async function transcribe(config, key, options, timeoutMs) {
  if (!options.audio) fail(EXIT.usage, "Give an --audio file.");
  const data = readInput(options.audio, LIMITS.audio, "Audio");
  const form = new FormData();
  form.append("model", config.model);
  form.append("file", new Blob([data]), basename(options.audio));
  if (options.language) form.append("language", options.language);
  if (options.prompt) form.append("prompt", options.prompt);
  const response = await call(config, key, "/audio/transcriptions", { method: "POST", body: form }, timeoutMs);
  const body = await json(response);
  if (typeof body?.text !== "string") fail(EXIT.unavailable, "The provider returned no transcript.");
  process.stdout.write(body.text.trim() + "\n");
}

const SPEECH_FORMATS = ["mp3", "wav", "opus", "aac", "flac", "pcm"];

async function speak(config, key, options, timeoutMs) {
  if (!options.text) fail(EXIT.usage, "Give the --text to speak.");
  if (options.text.length > 4096) fail(EXIT.usage, "--text is longer than 4096 characters; split it.");
  const format = (options.format || "mp3").toLowerCase();
  if (!SPEECH_FORMATS.includes(format)) fail(EXIT.usage, `--format must be one of ${SPEECH_FORMATS.join(", ")}.`);
  const response = await call(config, key, "/audio/speech", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model: config.model, input: options.text, voice: options.voice || "alloy", response_format: format }),
  }, timeoutMs);
  const data = Buffer.from(await response.arrayBuffer());
  if (!data.length) fail(EXIT.unavailable, "The provider returned no audio.");
  if (data.length > LIMITS.speech) fail(EXIT.unavailable, "The audio is larger than expected and was not saved.");
  const target = options.out && extname(options.out)
    ? options.out
    : join(options.out || config.output_dir || "bootagent-output", `speech-${stamp()}.${format}`);
  process.stdout.write(writeOutput(target, data) + "\n");
}

const COMMANDS = {
  vision: { name: "describe", run: describe, timeout: 120 },
  "image-generation": { name: "generate", run: generate, timeout: 300 },
  "speech-to-text": { name: "transcribe", run: transcribe, timeout: 300 },
  "text-to-speech": { name: "speak", run: speak, timeout: 120 },
};

const ADAPTERS = {
  vision: "openai-chat-vision",
  "image-generation": "openai-images",
  "speech-to-text": "openai-audio-transcriptions",
  "text-to-speech": "openai-audio-speech",
};

async function main() {
  const [major] = process.versions.node.split(".").map(Number);
  if (!(major >= 18) || typeof fetch !== "function" || typeof FormData !== "function") {
    fail(EXIT.setup, `Node.js 18 or later is required; this is ${process.versions.node}.`);
  }
  const config = loadConfig();
  const command = COMMANDS[config.capability];
  if (!command || ADAPTERS[config.capability] !== config.adapter) {
    fail(EXIT.setup, `This version of the script cannot run ${config.capability} over ${config.adapter}. Reinstall the Skill from BootAgent.`);
  }
  const [subcommand, ...rest] = process.argv.slice(2);
  if (!subcommand || subcommand === "--help" || subcommand === "help") {
    process.stdout.write(`Usage: node scripts/run.mjs ${command.name} [options]\n       node scripts/run.mjs check\nSee SKILL.md for the options and exit codes.\n`);
    return;
  }
  if (subcommand === "check") {
    loadKey(config);
    process.stdout.write(`ready: ${config.capability} with ${config.model}\n`);
    return;
  }
  if (subcommand !== command.name) fail(EXIT.usage, `This Skill runs "${command.name}", not "${subcommand}".`);
  const options = parseArgs(rest);
  if (options._.length) fail(EXIT.usage, `Unexpected argument: ${options._[0]}`);
  const timeout = positiveInt(options.timeout, "timeout", command.timeout, 3600) * 1000;
  const key = loadKey(config);
  await command.run(config, key, options, timeout);
}

main().then(
  () => process.exit(EXIT.ok),
  (error) => {
    const code = error instanceof Failure ? error.code : EXIT.internal;
    process.stderr.write(redact(error instanceof Failure ? error.message : `Unexpected error: ${error?.message ?? error}`) + "\n");
    process.exit(code);
  },
);
